    state.learning ||= {foodAliases:{},frequentFoods:{},recipeLikes:{},lastCorrections:[],commandHistory:[],visionFoods:{}};
    state.learning.visionFoods ||= {};
    state.milestones ||= [];
    state.shoppingList ||= [];
    state.checkins ||= [];
    state.customExercises ||= [];
    state.customFoods ||= [];
    state.dayPlans ||= {};
    state.goalHistory ||= [];
    state.settings ||= {};
    if(state.settings.rpeTracking===undefined)state.settings.rpeTracking=true;
    if(state.settings.autoRest===undefined)state.settings.autoRest=true;
    if(state.settings.smartSupersetScroll===undefined)state.settings.smartSupersetScroll=true;
    state.settings.defaultRest ||= 90;
    if(state.settings.showPublicData===undefined)state.settings.showPublicData=true;
