    return `<td><input ${data} data-field="weight" type="number" step=".5" value="${s.weight??''}" placeholder="—"></td><td><input ${data} data-field="reps" type="number" value="${s.reps??''}" placeholder="—"></td><td><input ${data} data-field="rpe" type="number" min="1" max="10" step=".5" value="${s.rpe??''}" placeholder="—"></td>`;
