  function parseActivityText(text,name){
    const s=(text+' '+name).replace(/,/g,' ').replace(/\s+/g,' ').toLowerCase();
    const val=re=>{const m=s.match(re);return m?safeNum(m[1]):0};
    let type=/pickleball/.test(s)?'Pickleball':/soccer|football/.test(s)?'Soccer':/swim/.test(s)?'Swimming':/hike|hiking/.test(s)?'Hiking':/row|rowing/.test(s)?'Rowing':/elliptical/.test(s)?'Elliptical':/stair/.test(s)?'Stair climber':/hiit|high intensity/.test(s)?'HIIT':/strength|weight training|resistance training/.test(s)?'Strength training':/cycle|cycling|bike|biking/.test(s)?'Cycling':/walk|walking/.test(s)?'Walk':/run|running|jog/.test(s)?'Run':'Imported activity';
    let duration=val(/(?:time|duration|workout time|elapsed time)[^\d]{0,16}(\d+(?:\.\d+)?)\s*(?:min|minute)?/);
    if(!duration){const hm=s.match(/(?:(\d+)\s*(?:h|hr|hrs|hour|hours)\b)\s*(?:(\d+)\s*(?:m|min|mins|minute|minutes)\b)?/);if(hm)duration=safeNum(hm[1])*60+safeNum(hm[2]);}
    if(!duration)duration=val(/(\d+(?:\.\d+)?)\s*(?:min|mins|minute|minutes)\b/);
    if(!duration){const clock=s.match(/\b(\d{1,2}):(\d{2})(?::(\d{2}))?\b/);if(clock){duration=clock[3]?safeNum(clock[1])*60+safeNum(clock[2])+safeNum(clock[3])/60:safeNum(clock[1])+safeNum(clock[2])/60;}}
    let calories=val(/(?:active calories|active energy|workout calories|total calories|energy|calories|kcal|cal)[^\d]{0,16}(\d+(?:\.\d+)?)/);
    if(!calories){const cm=s.match(/(\d+(?:\.\d+)?)\s*(?:kcal|calories|cal)\b/);if(cm)calories=safeNum(cm[1]);}
    const dm=s.match(/(?:distance[^\d]{0,16})?(\d+(?:\.\d+)?)\s*(mi|mile|miles|km|kilometer|kilometers)\b/);
    let distance=dm?safeNum(dm[1]):0;
    if(dm){const u=dm[2];if(unitDistance()==='km'&&/^(?:mi|mile|miles)$/.test(u))distance=round1(distance*1.60934);if(unitDistance()==='mi'&&/^(?:km|kilometer|kilometers)$/.test(u))distance=round1(distance*0.621371);}
    const paceMatch=s.match(/(?:pace[^\d]{0,14})?(\d{1,2}:\d{2})\s*(?:\/|per\s*)?(mi|mile|miles|km|kilometer|kilometers)\b/);
    const pace=paceMatch?`${paceMatch[1]} /${/^(?:km|kilometer|kilometers)$/.test(paceMatch[2])?'km':'mi'}`:'';
    const steps=val(/(?:steps?)[^\d]{0,12}(\d+(?:\.\d+)?)/)||val(/(\d+(?:\.\d+)?)\s*steps?\b/);
    const environment=/outdoor|outside/.test(s)?'Outdoor':/indoor|treadmill/.test(s)?'Indoor':'Not specified';
    const sourceApp=/apple fitness|apple health|activity rings/.test(s)?'Apple Fitness / Health':/samsung health|galaxy/.test(s)?'Samsung Health':/garmin/.test(s)?'Garmin':/strava/.test(s)?'Strava':/fitbit/.test(s)?'Fitbit':/treadmill|machine/.test(s)?'Treadmill / machine':'Other screenshot';
    const fieldConfidence={type:type!=='Imported activity'?88:55,duration:duration?88:55,distance:distance?88:55,pace:pace?86:55,steps:steps?86:55,calories:calories?84:55};
    return {type,duration:round1(duration),calories:round1(calories),distance:round1(distance),pace,steps:Math.round(steps),environment,sourceApp,fieldConfidence};
  }
