      <div class="quick-actions">${quick('📸','Veyra Lens','Food, labels, activity','lens')}${quick('🎙️','Talk to Veyra','Log or ask','voice')}${quick('🍲','Build a meal','Cuisine + pantry','recipeFinder')}${quick('📲','Import Activity','Any fitness screenshot','activityImport')}${quick('🏋️','Veyra Live','Start training','startWorkout')}${quick('▶','Replay','Search your history','replay')}</div>
