  /* ---------- Action/voice/navigation glue ---------- */
  function handleCommandV2(text){const s=String(text||'').trim(),l=s.toLowerCase();if(!s)return;
    if(/edit|change|set/.test(l)&&/(calorie|protein|macro|goal|target)/.test(l))return quickGoalsModal();
    if(l.includes('import')&&(l.includes('activity')||l.includes('watch')||l.includes('apple')||l.includes('samsung')))return lens('activity');
    if(l.includes('start')&&(l.includes('push')||l.includes('pull')||l.includes('leg')||l.includes('workout'))){const named=state.routines.find(x=>l.includes(x.name.toLowerCase().replace(' day','')))||state.routines.find(x=>(l.includes('push')&&/push/i.test(x.name))||(l.includes('pull')&&/pull/i.test(x.name))||(l.includes('leg')&&/leg/i.test(x.name)));return named?startWorkoutV2(named.id):workoutPickerModal()}
    if(l.includes('water')){const m=l.match(/\d+(?:\.\d+)?/);if(!m)return waterModalV2();const n=+m[0];state.water[today()]=(state.water[today()]||0)+n;touchStreak();save();render();return toast(`${n} ${state.profile.units==='metric'?'mL':'oz'} water logged`)}
    if(/\b(ran|run|walk|walked|cycled|bike|hiked|swam|swim|pickleball|soccer|football|basketball|tennis|rowed|rowing|elliptical|stairmaster|stair machine)\b/.test(l)){const duration=+(l.match(/(\d+(?:\.\d+)?)\s*(?:mins?|minutes?)\b/)||[])[1]||0,dm=l.match(/(\d+(?:\.\d+)?)\s*(miles?|mi\b|kms?|km\b|kilometers?)\b/);let dist=dm?+dm[1]:0;if(dm){const said=/^(?:km|kms|kilometers?)$/.test(dm[2])?'km':'mi',want=unitDistance();if(said==='km'&&want==='mi')dist=round1(dist*.621371);if(said==='mi'&&want==='km')dist=round1(dist*1.60934)}let type=/walk/.test(l)?'Walk':/bike|cycl/.test(l)?'Cycling':/swam|swim/.test(l)?'Swimming':/hike/.test(l)?'Hike':/pickleball/.test(l)?'Pickleball':/soccer|football/.test(l)?'Soccer':/basketball/.test(l)?'Basketball':/tennis/.test(l)?'Tennis':/row/.test(l)?'Rowing':/elliptical/.test(l)?'Elliptical':/stair/.test(l)?'Stair machine':'Run';return activityManual({type,environment:/\b(indoors?|inside|treadmill)\b/.test(l)?'Indoor':/\b(outdoors?|outside)\b/.test(l)?'Outdoor':'',duration:duration||'',distance:dist||'',calories:'',time:now().toTimeString().slice(0,5),source:'voice — activity details confirmed by user',confidence:85})}
    if(/\b(ate|had)\b/.test(l)){return window.smartFoodSearch?window.smartFoodSearch(s,/\bbreakfast\b/i.test(s)?'Breakfast':/\blunch\b/i.test(s)?'Lunch':/\bdinner\b/i.test(s)?'Dinner':'Snack'):addFoodModalV2('Snack',{name:s.replace(/.*?\b(ate|had)\b\s*/i,'').trim(),cal:'',p:'',c:'',f:'',fiber:'',sugar:'',time:now().toTimeString().slice(0,5),meal:'Snack',confidence:60,source:'voice — nutrition needs confirmation'})}
    if(/progress|graph/.test(l))return go('progress');if(/recipe|eat|pantry|protein|cuisine|sleep|recovery|workout/.test(l))return openCoachWithV2(s);openCoachWithV2(s);
  }
