  /* ---------- Fix PR milestone semantics: only celebrate a new session best ---------- */
  finishWorkoutV2=function(){
    if(!liveWorkout)return;clearInterval(window._veyraElapsed);clearInterval(restTimer);if(window._veyraSetTimer?.interval)clearInterval(window._veyraSetTimer.interval);window._veyraSetTimer=null;
    const before={};for(const e of liveWorkout.exercises)before[e.name]=exerciseStats(e.name);
    const mins=Math.max(1,Math.round((Date.now()-liveWorkout.start)/60000));const saved=structuredClone({...liveWorkout,date:today(),duration:mins});state.workouts.push(saved);
    state.activities.push({id:uid(),date:today(),time:now().toTimeString().slice(0,5),type:liveWorkout.routine,duration:mins,distance:0,calories:Math.round(mins*5.5),source:'Veyra Live estimate',confidence:65});
    const improvements=[];
    for(const e of saved.exercises){const after=exerciseStats(e.name),old=before[e.name];if(!after)continue;if(!old){improvements.push({icon:'✨',title:`${e.name} baseline saved`,body:'Your first completed set data is now the baseline for future comparisons.'});continue}let improved=false,delta=0,unit=unitWeight(),body='';if(e.kind==='time'){delta=after.bestSeconds-old.bestSeconds;unit='sec';improved=delta>0;body=`New best hold: ${after.bestSeconds} sec.`}else if(e.kind==='distance'){delta=after.bestDistance-old.bestDistance;unit=unitDistance();improved=delta>0;body=`New best distance: ${round1(after.bestDistance)} ${unit}.`}else{delta=after.bestWeight-old.bestWeight;improved=delta>0;if(!improved&&after.bestE1RM>old.bestE1RM+.5){delta=after.bestE1RM-old.bestE1RM;unit=`${unitWeight()} e1RM`;improved=true;body=`Estimated strength best: ${round1(after.bestE1RM)} ${unitWeight()}.`}else body=`New best load: ${round1(after.bestWeight)} ${unitWeight()}.`}if(improved)improvements.push({icon:'🏆',title:`${e.name}: +${round1(delta)} ${unit}`,body:`${body} Since your first log: ${after.delta>0?`+${round1(after.delta)} ${e.kind==='time'?'sec':e.kind==='distance'?unitDistance():unitWeight()}`:'trend updated'}.`});}
    for(const m of improvements)state.milestones.push({...m,date:today(),id:uid()});liveWorkout=null;touchStreak();save();closeModal();render();openModal('Workout complete',`<div class="post-workout-hero"><div class="celebrate">${improvements.some(x=>x.icon==='🏆')?'🏆':'✅'}</div><span class="eyebrow">VEYRA LIVE</span><h2>Workout saved</h2><p class="muted">${mins} minutes • ${saved.exercises.length} exercises • every completed set now feeds your exercise graphs.</p></div>${improvements.length?`<div class="pr-list">${improvements.map(x=>`<div class="pr-pop"><b>${x.icon} ${esc(x.title)}</b><small>${esc(x.body)}</small></div>`).join('')}</div>`:`<div class="callout">No PR needed for a workout to count. Consistent comparable sessions build your trend.</div>`}<div class="stack-actions"><button id="viewStrengthProgress" class="primary">View exercise graphs</button><button id="doneWorkoutSummary" class="secondary">Done</button></div>`);$('#viewStrengthProgress').onclick=()=>{closeModal();go('progress')};$('#doneWorkoutSummary').onclick=closeModal;
  };

