    if(!(goal>0))return `<button class="card metric metric-unset" data-action="editGoals"><div class="metric-top"><div><small>${label}</small><div class="big">${fmt(value)}<small>${unit}</small></div></div><div class="metric-icon">${icon}</div></div><small>Set your ${label.toLowerCase()} goal →</small><div class="progress-track"><div class="progress-fill" style="width:0%"></div></div></button>`;
